alter table public.organization_college_ratings add column if not exists coaches smallint check (coaches between 1 and 5);
create table if not exists public.organization_coach_ratings (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,coach_id uuid not null references public.college_coaches(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,communication smallint check (communication between 1 and 5),responsiveness smallint check (responsiveness between 1 and 5),follow_through smallint check (follow_through between 1 and 5),recruiting_experience smallint check (recruiting_experience between 1 and 5),organization_relationship smallint check (organization_relationship between 1 and 5),overall_experience smallint check (overall_experience between 1 and 5),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,coach_id,user_id));
alter table public.organization_coach_ratings enable row level security;
create policy "org members read coach ratings" on public.organization_coach_ratings for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=organization_coach_ratings.organization_id and m.user_id=auth.uid() and m.status='active'));
create policy "staff manage own coach rating" on public.organization_coach_ratings for all to authenticated using (user_id=auth.uid() and exists(select 1 from public.organization_members m where m.organization_id=organization_coach_ratings.organization_id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin','advisor'))) with check (user_id=auth.uid() and exists(select 1 from public.organization_members m where m.organization_id=organization_coach_ratings.organization_id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin','advisor')));
create index organization_coach_ratings_lookup on public.organization_coach_ratings(organization_id,coach_id);